SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, SUM(credit_limit) AS total_credit_limit, COUNT(*) AS cnt, RANK() OVER (ORDER BY SUM(credit_limit) DESC) AS credit_limit_rank FROM customers GROUP BY CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY signup_cohort;
